import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"涉江","description":"","frontmatter":{"title":"涉江","date":"2026-11-24T00:00:00.000Z","seq":15,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"屈原","source_book":"楚辞","prev":{"text":"惜诵","link":"/blogs/楚辞/惜诵.html"},"next":{"text":"哀郢","link":"/blogs/楚辞/哀郢.html"}},"headers":[],"relativePath":"blogs/楚辞/涉江.md","filePath":"blogs/楚辞/涉江.md"}'),o={name:"blogs/楚辞/涉江.md"};function l(n,a,c,m,z,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="涉江" tabindex="-1">涉江 <a class="header-anchor" href="#涉江" aria-label="Permalink to &quot;涉江&quot;">​</a></h1><p class="poem-meta">先秦 · 屈原　·　九章</p><div class="poem"><p class="poem-stanza">余幼好此奇服兮，年既老而不衰。</p><p class="poem-stanza">带长铗之陆离兮，冠切云之崔嵬，被明月兮佩宝璐。</p><p class="poem-stanza">世混浊而莫余知兮，吾方高驰而不顾。</p><p class="poem-stanza">驾青虬兮骖白螭，吾与重华游兮瑶之圃。</p><p class="poem-stanza">登昆仑兮食玉英，与天地兮同寿，与日月兮同光。</p><p class="poem-stanza">哀南夷之莫吾知兮，旦余济乎江湘。</p><p class="poem-stanza">乘鄂渚而反顾兮，欸秋冬之绪风。</p><p class="poem-stanza">步余马兮山皋，邸余车兮方林。</p><p class="poem-stanza">乘舲船余上沅兮，齐吴榜以击汰。</p><p class="poem-stanza">船容与而不进兮，淹回水而疑滞。</p><p class="poem-stanza">朝发枉渚兮，夕宿辰阳。</p><p class="poem-stanza">苟余心其端直兮，虽僻远之何伤。</p><p class="poem-stanza">入溆浦余儃徊兮，迷不知吾所如。</p><p class="poem-stanza">深林杳以冥冥兮，猿狖之所居。</p><p class="poem-stanza">山峻高以蔽日兮，下幽晦以多雨。</p><p class="poem-stanza">霰雪纷其无垠兮，云霏霏而承宇。</p><p class="poem-stanza">哀吾生之无乐兮，幽独处乎山中。</p><p class="poem-stanza">吾不能变心而从俗兮，固将愁苦而终穷。</p><p class="poem-stanza">接舆髡首兮，桑扈臝行。</p><p class="poem-stanza">忠不必用兮，贤不必以。</p><p class="poem-stanza">伍子逢殃兮，比干菹醢。</p><p class="poem-stanza">与前世而皆然兮，吾又何怨乎今之人！</p><p class="poem-stanza">余将董道而不豫兮，固将重昏而终身！</p><p class="poem-stanza">乱曰：</p><p class="poem-stanza">鸾鸟凤皇，日以远兮。</p><p class="poem-stanza">燕雀乌鹊，巢堂坛兮。</p><p class="poem-stanza">露申辛夷，死林薄兮。</p><p class="poem-stanza">腥臊并御，芳不得薄兮。</p><p class="poem-stanza">阴阳易位，时不当兮。</p><p class="poem-stanza">怀信佗傺，忽乎吾将行兮！</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
